.sl-smartcatalog-section {
    background-color: var(--smartlearn-bg);
    color: var(--smartlearn-text);
    position: relative;
    font-family: var(--smartlearn-body-font, system-ui, -apple-system, sans-serif);
}
.sl-smartcatalog-section h2, .sl-smartcatalog-section h3, .sl-smartcatalog-section h4, .sl-smartcatalog-section h5 { font-family: var(--smartlearn-heading-font, inherit); }
.sl-smartcatalog-section .sl-text-primary { color: var(--smartlearn-primary); }
.sl-smartcatalog-section .sl-text-emphasis { color: var(--smartlearn-text); }
.sl-smartcatalog-section .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-smartcatalog-section .sc-border { border-color: var(--smartlearn-card-border); }
.sl-smartcatalog-section .sc-card-radius { border-radius: var(--smartlearn-radius, 1rem); }
.sl-smartcatalog-section .sl-max-w-700 { max-width: 700px; }
.sl-smartcatalog-section .sc-badge-subtle {
    background-color: var(--smartlearn-card-bg);
    background-color: color-mix(in oklab, var(--smartlearn-primary) 14%, var(--smartlearn-card-bg));
    color: var(--smartlearn-primary);
    border: 1px solid var(--smartlearn-card-border);
}
.sl-smartcatalog-section .sc-badge-accent {
    background-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
}
.sl-smartcatalog-section .sc-badge-neutral {
    background-color: var(--smartlearn-bg);
    color: var(--smartlearn-text);
    border-color: var(--smartlearn-card-border);
}
.sl-smartcatalog-section .sc-input {
    background-color: var(--smartlearn-input-bg);
    border-color: var(--smartlearn-input-border);
    color: var(--smartlearn-text);
}
.sl-smartcatalog-section .sc-input::placeholder { color: var(--smartlearn-text-muted); }
.sl-smartcatalog-section .sc-btn-primary {
    background-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
    border: 1px solid var(--smartlearn-btn-bg);
    transition: background-color 0.2s ease, border-color 0.2s ease;
}
.sl-smartcatalog-section .sc-btn-primary:hover,
.sl-smartcatalog-section .sc-btn-primary:focus-visible {
    background-color: var(--smartlearn-btn-hover-bg);
    border-color: var(--smartlearn-btn-hover-bg);
    color: var(--smartlearn-btn-text);
}
.sl-smartcatalog-section .sc-btn-outline {
    background-color: transparent;
    color: var(--smartlearn-text);
    border: 1px solid var(--smartlearn-card-border);
    transition: background-color 0.2s ease, color 0.2s ease, border-color 0.2s ease;
}
.sl-smartcatalog-section .sc-btn-outline:hover,
.sl-smartcatalog-section .sc-btn-outline:focus-visible {
    background-color: var(--smartlearn-btn-bg);
    border-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
}
.sl-smartcatalog-section .sc-tabs .sc-tab-btn {
    background-color: var(--smartlearn-card-bg);
    color: var(--smartlearn-text);
    border: 1px solid var(--smartlearn-card-border);
    transition: transform 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.04);
}
.sl-smartcatalog-section .sc-tabs .sc-tab-btn.is-active {
    background-color: var(--smartlearn-btn-bg);
    border-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
}
.sl-smartcatalog-section .sc-filters-card {
    background-color: var(--smartlearn-card-bg);
    border: 1px solid var(--smartlearn-card-border);
}
.sl-smartcatalog-section .sc-cat-pill {
    background-color: var(--smartlearn-bg);
    border: 1px solid var(--smartlearn-card-border);
    color: var(--smartlearn-text-muted);
    font-weight: 600;
    padding: 0.4rem 1rem;
    transition: background-color 0.2s ease, color 0.2s ease, border-color 0.2s ease;
}
.sl-smartcatalog-section .sc-cat-pill .sc-cat-count {
    background-color: var(--smartlearn-card-bg);
    color: var(--smartlearn-text);
}
.sl-smartcatalog-section .sc-cat-pill:hover,
.sl-smartcatalog-section .sc-cat-pill.active {
    background-color: var(--smartlearn-btn-bg);
    border-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
}
.sl-smartcatalog-section .sc-card-img-wrap {
    height: 190px;
    background-color: var(--smartlearn-bg);
    overflow: hidden;
}
.sl-smartcatalog-section .sc-card-img { height: 100%; transition: transform 0.5s ease; }
.sl-smartcatalog-section .sc-card,
.sl-smartcatalog-section .sc-program-row-card {
    background-color: var(--smartlearn-card-bg);
    border: 1px solid var(--smartlearn-card-border);
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}
.sl-smartcatalog-section .sc-avatar-sm {
    width: 32px;
    height: 32px;
    font-size: 0.75rem;
    background-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
}
.sl-smartcatalog-section .sc-avatar-lg {
    width: 88px;
    height: 88px;
    font-size: 1.5rem;
    background-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
}
.sl-smartcatalog-section .sc-card-wrapper { position: relative; }
.sl-smartcatalog-section .sc-hover-popover {
    display: none;
    position: absolute;
    top: 50%;
    inset-inline-start: calc(100% + 14px);
    transform: translateY(-50%);
    width: 320px;
    background-color: var(--smartlearn-card-bg);
    border: 1px solid var(--smartlearn-card-border);
    color: var(--smartlearn-text);
    z-index: 1050;
    pointer-events: auto;
}
.sl-smartcatalog-section .sc-hover-popover::after {
    content: "";
    position: absolute;
    top: 0;
    bottom: 0;
    width: 18px;
    inset-inline-end: 100%;
}
.sl-smartcatalog-section .sc-hover-popover.is-flipped {
    inset-inline-start: auto;
    inset-inline-end: calc(100% + 14px);
}
.sl-smartcatalog-section .sc-hover-popover.is-flipped::after {
    inset-inline-end: auto;
    inset-inline-start: 100%;
}
.sl-smartcatalog-section .sl-focus-ring:focus-visible {
    outline: 3px solid var(--smartlearn-primary);
    outline-offset: 3px;
}
@media (min-width: 992px) {
    .sl-smartcatalog-section .sc-card-wrapper:hover .sc-hover-popover,
    .sl-smartcatalog-section .sc-card-wrapper:focus-within .sc-hover-popover { display: block; }
}
@media (hover: hover) and (prefers-reduced-motion: no-preference) {
    .sl-smartcatalog-section .sc-tabs .sc-tab-btn:hover { transform: translateY(-2px); box-shadow: 0 6px 12px rgba(0, 0, 0, 0.08); }
    .sl-smartcatalog-section .sc-card:hover { transform: translateY(-6px); box-shadow: 0 16px 32px rgba(0, 0, 0, 0.1); }
    .sl-smartcatalog-section .sc-card:hover .sc-card-img { transform: scale(1.06); }
    .sl-smartcatalog-section .sc-program-row-card:hover { transform: translateY(-4px); box-shadow: 0 16px 32px rgba(0, 0, 0, 0.1); }
    .sl-smartcatalog-section .sc-hover-popover { animation: sl-smartcatalog-popin 0.2s ease forwards; }
}
@media (prefers-reduced-motion: reduce) {
    .sl-smartcatalog-section .sc-tabs .sc-tab-btn,
    .sl-smartcatalog-section .sc-card,
    .sl-smartcatalog-section .sc-card-img,
    .sl-smartcatalog-section .sc-program-row-card,
    .sl-smartcatalog-section .sc-cat-pill,
    .sl-smartcatalog-section .sc-btn-primary,
    .sl-smartcatalog-section .sc-btn-outline { transition: none; }
}
@keyframes sl-smartcatalog-popin {
    from { opacity: 0; transform: translateY(-50%) scale(0.96); }
    to { opacity: 1; transform: translateY(-50%) scale(1); }
}

