(function() {
    const init = () => {
        document.querySelectorAll('.sl-smartcatalog-section').forEach((root) => {
            if (root.dataset.slInit === '1') return;
            root.dataset.slInit = '1';

            const uid = 'sc-' + Math.random().toString(36).slice(2, 8);
            const bindLabel = (labelSel, inputSel, suffix) => {
                const lbl = root.querySelector(labelSel);
                const inp = root.querySelector(inputSel);
                if (lbl && inp) {
                    const id = uid + '-' + suffix;
                    inp.id = id;
                    lbl.setAttribute('for', id);
                }
            };
            bindLabel('.sc-search-label', '.sc-search-input', 'search');
            bindLabel('.sc-sort-label', '.sc-sort-select', 'sort');
            bindLabel('.sc-level-label', '.sc-level-select', 'level');

            const showCourses = root.getAttribute('data-show-courses') !== 'false';
            const showPrograms = root.getAttribute('data-show-programs') !== 'false';
            const showTeachers = root.getAttribute('data-show-teachers') !== 'false';

            const tabBtns = Array.from(root.querySelectorAll('.sc-tab-btn'));
            const viewCourses = root.querySelector('.sc-view-courses');
            const viewPrograms = root.querySelector('.sc-view-programs');
            const viewTeachers = root.querySelector('.sc-view-teachers');
            const levelWrap = root.querySelector('.sc-level-wrap');
            const searchInput = root.querySelector('.sc-search-input');
            const sortSelect = root.querySelector('.sc-sort-select');
            const levelSelect = root.querySelector('.sc-level-select');
            const catPills = Array.from(root.querySelectorAll('.sc-cat-pill'));
            const allCatCountEl = root.querySelector('.sc-cat-count');
            const resultsCountBadge = root.querySelector('.sc-results-count');
            const noResultsMsg = root.querySelector('.sc-no-results');

            tabBtns.forEach((btn) => {
                const type = btn.getAttribute('data-type');
                if ((type === 'course' && !showCourses) || (type === 'program' && !showPrograms) || (type === 'teacher' && !showTeachers)) {
                    btn.style.display = 'none';
                }
            });

            const firstEnabled = tabBtns.find((b) => b.style.display !== 'none') || tabBtns[0];
            let currentTab = firstEnabled ? (firstEnabled.getAttribute('data-type') || 'course') : 'course';
            let selectedCategory = 'all';

            const syncTabUI = () => {
                tabBtns.forEach((b) => {
                    const active = b.getAttribute('data-type') === currentTab;
                    b.classList.toggle('is-active', active);
                    b.setAttribute('aria-selected', active ? 'true' : 'false');
                });
                if (viewCourses) viewCourses.style.display = currentTab === 'course' ? 'block' : 'none';
                if (viewPrograms) viewPrograms.style.display = currentTab === 'program' ? 'block' : 'none';
                if (viewTeachers) viewTeachers.style.display = currentTab === 'teacher' ? 'block' : 'none';
                if (levelWrap) levelWrap.style.display = currentTab === 'teacher' ? 'none' : '';
            };

            const applyFilters = () => {
                const query = (searchInput ? searchInput.value : '').toLowerCase().trim();
                const selectedLevel = currentTab === 'teacher' ? 'all' : (levelSelect ? levelSelect.value : 'all');
                const sortMode = sortSelect ? sortSelect.value : 'recent';

                const viewClass = currentTab === 'course' ? '.sc-view-courses' : currentTab === 'program' ? '.sc-view-programs' : '.sc-view-teachers';
                const activeContainer = root.querySelector(viewClass);
                if (!activeContainer) return;

                const items = Array.from(activeContainer.querySelectorAll('.sc-catalog-item'));
                if (allCatCountEl) allCatCountEl.textContent = String(items.length);

                let visibleCount = 0;
                items.forEach((item) => {
                    const title = (item.querySelector('.sc-item-title')?.textContent || '').toLowerCase();
                    const desc = (item.querySelector('.sc-item-desc')?.textContent || '').toLowerCase();
                    const itemCats = (item.getAttribute('data-category') || '').toLowerCase().trim().split(/\s+/);
                    const itemLevel = (item.getAttribute('data-level') || '').toLowerCase();

                    const matchesQuery = !query || title.includes(query) || desc.includes(query);
                    const matchesCat = selectedCategory === 'all' || itemCats.includes(selectedCategory);
                    const matchesLevel = selectedLevel === 'all' || itemLevel === selectedLevel;

                    if (matchesQuery && matchesCat && matchesLevel) {
                        item.style.display = '';
                        visibleCount++;
                    } else {
                        item.style.display = 'none';
                    }
                });

                const parentGrid = activeContainer.querySelector('.sc-items-grid') || activeContainer.querySelector('.row') || activeContainer.querySelector('.d-flex.flex-column');
                if (parentGrid && items.length > 0) {
                    const sortedItems = [...items].sort((a, b) => {
                        const titleA = a.querySelector('.sc-item-title')?.textContent || '';
                        const titleB = b.querySelector('.sc-item-title')?.textContent || '';
                        const popA = parseInt(a.getAttribute('data-popularity') || '0', 10);
                        const popB = parseInt(b.getAttribute('data-popularity') || '0', 10);
                        const dateA = new Date(a.getAttribute('data-date') || '2026-01-01');
                        const dateB = new Date(b.getAttribute('data-date') || '2026-01-01');
                        if (sortMode === 'az') return titleA.localeCompare(titleB);
                        if (sortMode === 'za') return titleB.localeCompare(titleA);
                        if (sortMode === 'popular') return popB - popA;
                        return dateB - dateA;
                    });
                    sortedItems.forEach((el) => parentGrid.appendChild(el));
                }

                if (resultsCountBadge) {
                    const labelAttr = currentTab === 'course' ? 'data-label-course' : currentTab === 'program' ? 'data-label-program' : 'data-label-teacher';
                    const label = resultsCountBadge.getAttribute(labelAttr) || 'Items';
                    resultsCountBadge.textContent = `${visibleCount} ${label}`;
                }
                if (noResultsMsg) {
                    noResultsMsg.style.display = visibleCount === 0 ? 'block' : 'none';
                }
            };

            tabBtns.forEach((btn) => {
                btn.addEventListener('click', (e) => {
                    e.preventDefault();
                    currentTab = btn.getAttribute('data-type') || 'course';
                    syncTabUI();
                    applyFilters();
                });
            });

            catPills.forEach((pill) => {
                pill.addEventListener('click', (e) => {
                    e.preventDefault();
                    catPills.forEach((p) => {
                        p.classList.remove('active');
                        p.setAttribute('aria-pressed', 'false');
                    });
                    pill.classList.add('active');
                    pill.setAttribute('aria-pressed', 'true');
                    selectedCategory = pill.getAttribute('data-category') || 'all';
                    applyFilters();
                });
            });

            if (searchInput) searchInput.addEventListener('input', applyFilters);
            if (sortSelect) sortSelect.addEventListener('change', applyFilters);
            if (levelSelect) levelSelect.addEventListener('change', applyFilters);

            root.querySelectorAll('.sc-card-wrapper').forEach((wrapper) => {
                const popover = wrapper.querySelector('.sc-hover-popover');
                if (!popover) return;
                const updateFlip = () => {
                    const rect = wrapper.getBoundingClientRect();
                    const isRtl = getComputedStyle(root).direction === 'rtl';
                    const fitsInlineEnd = isRtl ? rect.left - 340 >= 8 : rect.right + 340 <= window.innerWidth - 8;
                    popover.classList.toggle('is-flipped', !fitsInlineEnd);
                };
                wrapper.addEventListener('mouseenter', updateFlip);
                wrapper.addEventListener('focusin', updateFlip);
            });

            syncTabUI();
            applyFilters();
        });
    };
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();
